import * as ui from "../bindings/ui";
import { HandlerAction } from "../core/Action";
import { Disposable, disposeAll } from "../core/Disposable";
import { EventRouter, GlobalKeyHandler } from "../core/EventRouter";
import { keyboardFocusVisible } from "../core/FocusVisibility";
import {
  AlignItems,
  BorderStyle,
  CursorStyle,
  FlexDirection,
  HandleValue,
  JustifyContent,
  KeyEventType,
  PointerEventType,
  SemanticRole,
  TextAlign,
  TextVerticalAlign,
  Unit,
} from "../core/ffi";
import { Theme, activeTheme } from "../core/Theme";
import { FlexBox, Portal, Text } from "../nodes";

const PANEL_EDGE_PADDING: f32 = 8.0;
const CHEVRON_BOX_SIZE: f32 = 16.0;

function isActivationKey(key: string): bool {
  return key == "Enter" || key == " " || key == "ArrowDown";
}

function handleDropdownOverlayClick(): void {
  Dropdown.hideActiveDropdown();
}

export class DropdownItem {
  constructor(readonly value: string, readonly label: string = value) {}
}

class DropdownOptionNode extends FlexBox {
  private readonly labelNode: Text;
  private owner: Dropdown | null = null;
  private slotIndex: i32 = -1;

  constructor() {
    super();
    this.labelNode = new Text("");
    this.semanticRole(SemanticRole.ListItem);
    this.flexDirection(FlexDirection.Row);
    this.alignItems(AlignItems.Center);
    this.cursor(CursorStyle.Pointer);
    this.focusable(false);
    this.requireInteractive();
    this.child(this.labelNode);
  }

  bindOwner(owner: Dropdown, slotIndex: i32): this {
    this.owner = owner;
    this.slotIndex = slotIndex;
    return this;
  }

  setLabel(label: string): this {
    this.semanticLabel(label);
    this.labelNode.text(label);
    return this;
  }

  applyTheme(theme: Theme, highlighted: bool, selected: bool): void {
    this.semanticSelected(selected);
    this.padding(10.0, 6.0, 10.0, 6.0);
    this.cornerRadius(theme.spacing.xs);
    this.bgColor(highlighted ? theme.colors.background : theme.colors.surface);
    this.labelNode.font(theme.fonts.body, theme.fonts.sizeBody);
    this.labelNode.textColor(selected ? theme.colors.accent : theme.colors.textPrimary);
  }

  _handlePointerEvent(eventType: PointerEventType, x: f32, y: f32, modifiers: u32 = 0): void {
    super._handlePointerEvent(eventType, x, y, modifiers);
    const owner = this.owner;
    if (owner === null) {
      return;
    }
    if (eventType == PointerEventType.Enter) {
      owner.highlightIndex(this.slotIndex);
      return;
    }
    if (eventType == PointerEventType.Up) {
      owner.selectHighlighted();
    }
  }
}

export class Dropdown extends FlexBox implements GlobalKeyHandler {
  private static activeInstance: Dropdown | null = null;
  private static readonly collapsedChevron: string = "▼";
  private static readonly expandedChevron: string = "▲";
  private readonly valueNode: Text;
  private readonly spacerNode: FlexBox;
  private readonly chevronHost: FlexBox;
  private readonly chevronNode: Text;
  private readonly popupRoot: Portal;
  private readonly overlayNode: FlexBox;
  private readonly panelNode: FlexBox;
  private readonly optionNodes: Array<DropdownOptionNode> = new Array<DropdownOptionNode>();
  private readonly itemsValue: Array<DropdownItem> = new Array<DropdownItem>();
  private readonly disposables: Array<Disposable> = new Array<Disposable>();
  private disposed: bool = false;
  private openState: bool = false;
  private pointerPressedState: bool = false;
  private focusedState: bool = false;
  private keyFilterToken: u32 = 0;
  private semanticScopeToken: u32 = 0;
  private selectedIndexValue: i32 = -1;
  private highlightedIndexValue: i32 = -1;
  private changedCallback: ((item: DropdownItem, index: i32) => void) | null = null;

  constructor() {
    super();
    this.valueNode = new Text("");
    this.spacerNode = new FlexBox().flexGrow(1.0);
    this.chevronHost = new FlexBox()
      .width(CHEVRON_BOX_SIZE, Unit.Pixel)
      .height(CHEVRON_BOX_SIZE, Unit.Pixel)
      .alignItems(AlignItems.Center)
      .justifyContent(JustifyContent.Center);
    this.chevronNode = new Text(Dropdown.collapsedChevron)
      .width(100.0, Unit.Star)
      .height(100.0, Unit.Star);
    const popupRoot = new Portal();
    const overlayNode = new FlexBox()
      .positionAbsolute()
      .position(0.0, 0.0)
      .width(100.0, Unit.Star)
      .height(100.0, Unit.Star)
      .onClick(handleDropdownOverlayClick);
    const panelNode = new FlexBox()
      .positionAbsolute()
      .flexDirection(FlexDirection.Column);
    this.popupRoot = popupRoot;
    this.overlayNode = overlayNode;
    this.panelNode = panelNode;
    popupRoot
      .positionAbsolute()
      .position(0.0, 0.0)
      .width(100.0, Unit.Star)
      .height(100.0, Unit.Star);
    panelNode.semanticRole(SemanticRole.List);
    panelNode.semanticLabel("Dropdown options");
    overlayNode.child(panelNode);
    this.semanticRole(SemanticRole.ComboBox);
    this.focusable(true);
    this.requireInteractive();
    this.reflectSemanticDisabledFromEnabled();
    this.cursor(CursorStyle.Pointer);
    this.flexDirection(FlexDirection.Row);
    this.alignItems(AlignItems.Center);
    this.child(this.valueNode);
    this.child(this.spacerNode);
    this.chevronHost.child(this.chevronNode);
    this.child(this.chevronHost);
    this.child(this.popupRoot);
    this.track(activeTheme.addAction(new HandlerAction<Dropdown, Theme>(this, (dropdown: Dropdown, _theme: Theme): void => {
      dropdown.handleThemeChanged();
    })));
    this.track(keyboardFocusVisible.addAction(new HandlerAction<Dropdown, bool>(this, (dropdown: Dropdown, _visible: bool): void => {
      dropdown.handleThemeChanged();
    })));
    this.semanticExpanded(false);
    this.valueNode.verticalAlign(TextVerticalAlign.Center);
    this.chevronNode
      .textAlign(TextAlign.Center)
      .verticalAlign(TextVerticalAlign.Center);
    this.handleThemeChanged();
  }

  get selectedIndex(): i32 {
    return this.selectedIndexValue;
  }

  items(items: Array<DropdownItem>): this {
    this.clearItems();
    for (let index = 0; index < items.length; ++index) {
      this.itemsValue.push(unchecked(items[index]));
    }
    if (this.selectedIndexValue >= this.itemsValue.length) {
      this.selectedIndexValue = this.itemsValue.length > 0 ? 0 : -1;
    } else if (this.selectedIndexValue < 0 && this.itemsValue.length > 0) {
      this.selectedIndexValue = 0;
    }
    this.ensureOptionNodes();
    this.syncValueLabel();
    this.syncOptionVisuals();
    return this;
  }

  onChanged(callback: ((item: DropdownItem, index: i32) => void) | null): this {
    this.changedCallback = callback;
    return this;
  }

  setSelectedIndex(index: i32): this {
    if (index < 0 || index >= this.itemsValue.length) {
      return this;
    }
    this.selectedIndexValue = index;
    this.highlightedIndexValue = index;
    this.syncValueLabel();
    this.syncOptionVisuals();
    return this;
  }

  destroy(): void {
    this.close();
    this.dispose();
    super.destroy();
  }

  static hideActiveDropdown(): void {
    const dropdown = Dropdown.activeInstance;
    if (dropdown !== null) {
      dropdown.close();
    }
  }

  highlightIndex(index: i32): void {
    if (index < 0 || index >= this.itemsValue.length || this.highlightedIndexValue == index) {
      return;
    }
    this.highlightedIndexValue = index;
    this.syncOptionVisuals();
  }

  selectHighlighted(): void {
    if (this.highlightedIndexValue < 0 || this.highlightedIndexValue >= this.itemsValue.length) {
      return;
    }
    this.selectedIndexValue = this.highlightedIndexValue;
    this.syncValueLabel();
    this.syncOptionVisuals();
    const callback = this.changedCallback;
    if (callback !== null) {
      callback(unchecked(this.itemsValue[this.selectedIndexValue]), this.selectedIndexValue);
    }
    this.close();
  }

  handleGlobalKeyEvent(eventType: KeyEventType, key: string, modifiers: u32): bool {
    if (!this.openState || modifiers != 0) {
      return false;
    }
    if (eventType != KeyEventType.Down) {
      return false;
    }
    if (key == "Escape") {
      this.close();
      return true;
    }
    if (key == "Enter") {
      this.selectHighlighted();
      return true;
    }
    if (key == "Home") {
      this.highlightIndex(0);
      return true;
    }
    if (key == "End") {
      this.highlightIndex(this.itemsValue.length - 1);
      return true;
    }
    if (key == "ArrowDown") {
      this.moveHighlight(1);
      return true;
    }
    if (key == "ArrowUp") {
      this.moveHighlight(-1);
      return true;
    }
    return false;
  }

  _handlePointerEvent(eventType: PointerEventType, x: f32, y: f32, modifiers: u32 = 0): void {
    super._handlePointerEvent(eventType, x, y, modifiers);
    if (!this.isEnabled) {
      return;
    }
    if (eventType == PointerEventType.Leave) {
      this.pointerPressedState = false;
      this.handleThemeChanged();
      return;
    }
    if (eventType == PointerEventType.Down) {
      this.pointerPressedState = true;
      this.handleThemeChanged();
      return;
    }
    if (eventType == PointerEventType.Up && this.pointerPressedState) {
      this.pointerPressedState = false;
      if (this.openState) {
        this.close();
      } else {
        this.open();
      }
      this.handleThemeChanged();
    }
  }

  _handleKeyEvent(eventType: KeyEventType, key: string, modifiers: u32): void {
    super._handleKeyEvent(eventType, key, modifiers);
    if (!this.isEnabled || modifiers != 0 || eventType != KeyEventType.Down) {
      return;
    }
    if (!this.openState && isActivationKey(key)) {
      this.open();
      return;
    }
    if (!this.openState && key == "ArrowUp") {
      this.open();
      this.moveHighlight(-1);
    }
  }

  _handleFocusChanged(focused: bool): void {
    super._handleFocusChanged(focused);
    this.focusedState = focused;
    if (!focused && !this.openState) {
      this.pointerPressedState = false;
    }
    this.handleThemeChanged();
  }

  protected _onEffectiveEnabledChanged(_isEnabled: bool): void {
    if (!this.isEnabled) {
      this.close();
    }
    this.handleThemeChanged();
  }

  private open(): void {
    if (this.openState || this.itemsValue.length == 0 || this.builtHandle == 0) {
      return;
    }
    this.ensureOptionNodes();
    this.rebuildPanel();
    const popupBounds = this.popupRoot.builtHandle != 0 ? ui.tryGetBounds(this.popupRoot.builtHandle) : null;
    const overlayX = popupBounds !== null ? -unchecked(popupBounds[0]) : 0.0;
    const overlayY = popupBounds !== null ? -unchecked(popupBounds[1]) : 0.0;
    this.overlayNode
      .position(overlayX, overlayY)
      .width(ui.getViewportWidth(), Unit.Pixel)
      .height(ui.getViewportHeight(), Unit.Pixel);
    const bounds = this.tryGetViewportBounds();
    if (bounds !== null) {
      const width = unchecked(bounds[2]);
      const height = unchecked(bounds[3]);
      this.positionPanel(unchecked(bounds[0]), unchecked(bounds[1]) + height + 4.0, width);
    }
    this.popupRoot.addChildNode(this.overlayNode);
    this.openState = true;
    Dropdown.activeInstance = this;
    this.semanticExpanded(true);
    this.syncChevronGlyph();
    if (this.selectedIndexValue >= 0) {
      this.highlightedIndexValue = this.selectedIndexValue;
    } else if (this.itemsValue.length > 0) {
      this.highlightedIndexValue = 0;
    }
    this.syncOptionVisuals();
    if (this.keyFilterToken == 0) {
      this.keyFilterToken = EventRouter.pushKeyFilter(this);
    }
    if (this.semanticScopeToken == 0 && this.panelNode.builtHandle != <u64>HandleValue.Invalid) {
      this.semanticScopeToken = ui.pushSemanticScope(this.panelNode.builtHandle);
    }
    this.handleThemeChanged();
  }

  private tryGetViewportBounds(): Float32Array | null {
    if (this.builtHandle == 0) {
      return null;
    }
    return ui.tryGetBounds(this.builtHandle);
  }

  private positionPanel(x: f32, y: f32, width: f32): void {
    const panelHeight = <f32>this.itemsValue.length * 34.0 + 8.0;
    const maxX = <f32>Math.max(PANEL_EDGE_PADDING, ui.getViewportWidth() - width - PANEL_EDGE_PADDING);
    const maxY = <f32>Math.max(PANEL_EDGE_PADDING, ui.getViewportHeight() - panelHeight - PANEL_EDGE_PADDING);
    this.panelNode.position(
      <f32>Math.max(PANEL_EDGE_PADDING, Math.min(x, maxX)),
      <f32>Math.max(PANEL_EDGE_PADDING, Math.min(y, maxY)),
    );
    this.panelNode.width(width, Unit.Pixel);
  }

  private close(): void {
    if (!this.openState && this.overlayNode.parentNode === null) {
      return;
    }
    this.popupRoot.removeChildNode(this.overlayNode);
    this.openState = false;
    if (Dropdown.activeInstance === this) {
      Dropdown.activeInstance = null;
    }
    this.semanticExpanded(false);
    this.syncChevronGlyph();
    if (this.keyFilterToken != 0) {
      EventRouter.removeKeyFilter(this.keyFilterToken);
      this.keyFilterToken = 0;
    }
    if (this.semanticScopeToken != 0) {
      ui.removeSemanticScope(this.semanticScopeToken);
      this.semanticScopeToken = 0;
    }
    this.handleThemeChanged();
  }

  private rebuildPanel(): void {
    for (let index = 0; index < this.optionNodes.length; ++index) {
      this.panelNode.removeChildNode(unchecked(this.optionNodes[index]));
    }
    for (let index = 0; index < this.itemsValue.length; ++index) {
      const optionNode = unchecked(this.optionNodes[index]);
      optionNode.setLabel(unchecked(this.itemsValue[index]).label);
      this.panelNode.addChildNode(optionNode);
    }
  }

  private syncValueLabel(): void {
    if (this.selectedIndexValue >= 0 && this.selectedIndexValue < this.itemsValue.length) {
      this.valueNode.text(unchecked(this.itemsValue[this.selectedIndexValue]).label);
      this.semanticLabel(unchecked(this.itemsValue[this.selectedIndexValue]).label);
      return;
    }
    this.valueNode.text("");
  }

  private syncOptionVisuals(): void {
    const theme = activeTheme.value;
    for (let index = 0; index < this.itemsValue.length; ++index) {
      unchecked(this.optionNodes[index]).applyTheme(theme, index == this.highlightedIndexValue, index == this.selectedIndexValue);
    }
  }

  private moveHighlight(delta: i32): void {
    if (this.itemsValue.length == 0) {
      return;
    }
    let nextIndex = this.highlightedIndexValue;
    if (nextIndex < 0) {
      nextIndex = this.selectedIndexValue >= 0 ? this.selectedIndexValue : 0;
    }
    nextIndex += delta;
    if (nextIndex < 0) {
      nextIndex = this.itemsValue.length - 1;
    } else if (nextIndex >= this.itemsValue.length) {
      nextIndex = 0;
    }
    this.highlightIndex(nextIndex);
  }

  private clearItems(): void {
    this.close();
    this.itemsValue.length = 0;
    this.selectedIndexValue = -1;
    this.highlightedIndexValue = -1;
  }

  private ensureOptionNodes(): void {
    while (this.optionNodes.length < this.itemsValue.length) {
      const optionNode = new DropdownOptionNode().bindOwner(this, this.optionNodes.length);
      this.optionNodes.push(optionNode);
    }
  }

  private handleThemeChanged(): void {
    if (this.disposed) {
      return;
    }
    const theme = activeTheme.value;
    this.cursor(this.isEnabled ? CursorStyle.Pointer : CursorStyle.Default);
    this.cornerRadius(theme.spacing.sm);
    this.border(
      2.0,
      this.focusedState && this.isEnabled && keyboardFocusVisible.value ? theme.colors.focusRing : theme.colors.border,
      BorderStyle.Solid,
    );
    this.padding(theme.spacing.md, theme.spacing.sm, theme.spacing.md, theme.spacing.sm);
    this.bgColor(this.pointerPressedState && this.isEnabled ? theme.colors.background : theme.colors.surface);
    this.opacity(this.isEnabled ? 1.0 : 0.6);
    this.valueNode.font(theme.fonts.body, theme.fonts.sizeBody);
    this.valueNode.textColor(this.isEnabled ? theme.colors.textPrimary : theme.colors.textMuted);
    this.chevronHost
      .width(CHEVRON_BOX_SIZE, Unit.Pixel)
      .height(CHEVRON_BOX_SIZE, Unit.Pixel);
    this.chevronNode
      .font(theme.fonts.body, theme.fonts.sizeBody - 2.0)
      .textColor(theme.colors.textMuted);
    this.panelNode
      .padding(4.0, 4.0, 4.0, 4.0)
      .cornerRadius(theme.spacing.sm)
      .bgColor(theme.colors.surface)
      .border(1.0, theme.colors.border, BorderStyle.Solid);
    this.syncOptionVisuals();
  }

  private syncChevronGlyph(): void {
    this.chevronNode.text(this.openState ? Dropdown.expandedChevron : Dropdown.collapsedChevron);
  }

  private track(disposable: Disposable): void {
    this.disposables.push(disposable);
  }

  private dispose(): void {
    if (this.disposed) {
      return;
    }
    this.disposed = true;
    disposeAll(this.disposables);
  }
}
