import { BorderStyle, KeyEventType, SemanticCheckedState, SemanticRole, Unit } from "../core/ffi";
import { Theme, activeTheme } from "../core/Theme";
import { FlexBox } from "../nodes";
import { PressableLabeledControl } from "./internal/PressableLabeledControl";
import { RadioGroup } from "./RadioGroup";

export class RadioButton extends PressableLabeledControl {
  private readonly dotNode: FlexBox;
  private readonly valueText: string;
  private checkedValue: bool = false;
  private changedCallback: ((checked: bool) => void) | null = null;
  private ownerGroup: RadioGroup | null = null;

  constructor(value: string, label: string = value) {
    const indicatorNode = new FlexBox()
      .width(18.0, Unit.Pixel)
      .height(18.0, Unit.Pixel)
      .alignItems(1)
      .justifyContent(1);
    super(SemanticRole.Radio, label, indicatorNode);
    this.valueText = value;
    this.dotNode = new FlexBox()
      .positionAbsolute()
      .position(5.0, 5.0)
      .width(8.0, Unit.Pixel)
      .height(8.0, Unit.Pixel);
    indicatorNode.child(this.dotNode);
    this.semanticChecked(SemanticCheckedState.False);
    this.syncVisualState();
  }

  get value(): string {
    return this.valueText;
  }

  get checked(): bool {
    return this.checkedValue;
  }

  bindGroup(group: RadioGroup): this {
    this.ownerGroup = group;
    return this;
  }

  setChecked(flag: bool): this {
    this.applyChecked(flag, false);
    return this;
  }

  onChanged(callback: ((checked: bool) => void) | null): this {
    this.changedCallback = callback;
    return this;
  }

  _handleKeyEvent(eventType: KeyEventType, key: string, modifiers: u32): void {
    super._handleKeyEvent(eventType, key, modifiers);
    if (!this.isEnabled || eventType != KeyEventType.Down || modifiers != 0) {
      return;
    }
    const group = this.ownerGroup;
    if (group === null) {
      return;
    }
    if (key == "ArrowLeft" || key == "ArrowUp") {
      group.moveSelectionFrom(this, -1);
      return;
    }
    if (key == "ArrowRight" || key == "ArrowDown") {
      group.moveSelectionFrom(this, 1);
      return;
    }
    if (key == "Home") {
      group.selectFirstEnabled(true);
      return;
    }
    if (key == "End") {
      group.selectLastEnabled(true);
    }
  }

  protected handleActivated(): void {
    const group = this.ownerGroup;
    if (group !== null) {
      group.selectRadio(this, true);
      return;
    }
    this.applyChecked(true, true);
  }

  protected syncVisualState(): void {
    const theme = activeTheme.value;
    const outerColor = this.checkedValue
      ? (this.pressedState ? theme.colors.accentPressed : (this.hoveredState ? theme.colors.accentHovered : theme.colors.accent))
      : theme.colors.border;
    this.indicatorNode.cornerRadius(9.0);
    this.indicatorNode.border(1.0, outerColor, BorderStyle.Solid);
    this.indicatorNode.bgColor(theme.colors.surface);
    this.dotNode.cornerRadius(4.0);
    this.dotNode.position(5.0, 5.0);
    this.dotNode.bgColor(outerColor);
    this.dotNode.opacity(this.checkedValue ? 1.0 : 0.0);
  }

  applyChecked(flag: bool, emit: bool): void {
    if (this.checkedValue == flag) {
      return;
    }
    this.checkedValue = flag;
    this.semanticChecked(flag ? SemanticCheckedState.True : SemanticCheckedState.False);
    this.syncVisualState();
    if (emit) {
      const callback = this.changedCallback;
      if (callback !== null) {
        callback(flag);
      }
    }
  }
}
