import { BorderStyle, SemanticCheckedState, SemanticRole, Unit } from "../core/ffi";
import { Theme, activeTheme } from "../core/Theme";
import { FlexBox } from "../nodes";
import { PressableLabeledControl } from "./internal/PressableLabeledControl";

export class Switch extends PressableLabeledControl {
  private readonly thumbNode: FlexBox;
  private checkedValue: bool = false;
  private changedCallback: ((checked: bool) => void) | null = null;

  constructor(label: string) {
    const trackNode = new FlexBox()
      .width(42.0, Unit.Pixel)
      .height(24.0, Unit.Pixel)
      .clipToBounds(true);
    super(SemanticRole.Switch, label, trackNode);
    this.thumbNode = new FlexBox()
      .positionAbsolute()
      .position(3.0, 3.0)
      .width(18.0, Unit.Pixel)
      .height(18.0, Unit.Pixel);
    trackNode.alignItems(1).child(this.thumbNode);
    this.semanticChecked(SemanticCheckedState.False);
    this.syncVisualState();
  }

  get checked(): bool {
    return this.checkedValue;
  }

  setChecked(flag: bool): this {
    this.applyChecked(flag, false);
    return this;
  }

  onChanged(callback: ((checked: bool) => void) | null): this {
    this.changedCallback = callback;
    return this;
  }

  protected handleActivated(): void {
    this.applyChecked(!this.checkedValue, true);
  }

  protected syncVisualState(): void {
    const theme = activeTheme.value;
    const trackColor = this.checkedValue
      ? (this.pressedState ? theme.colors.accentPressed : (this.hoveredState ? theme.colors.accentHovered : theme.colors.accent))
      : (this.hoveredState ? theme.colors.background : theme.colors.surface);
    this.indicatorNode.cornerRadius(12.0);
    this.indicatorNode.border(1.0, this.checkedValue ? trackColor : theme.colors.border, BorderStyle.Solid);
    this.indicatorNode.bgColor(trackColor);
    this.thumbNode.position(this.checkedValue ? 21.0 : 3.0, 3.0);
    this.thumbNode.cornerRadius(9.0);
    this.thumbNode.bgColor(theme.colors.surface);
    this.thumbNode.border(1.0, this.checkedValue ? trackColor : theme.colors.border, BorderStyle.Solid);
  }

  private applyChecked(next: bool, emit: bool): void {
    if (this.checkedValue == next) {
      return;
    }
    this.checkedValue = next;
    this.semanticChecked(next ? SemanticCheckedState.True : SemanticCheckedState.False);
    this.syncVisualState();
    if (emit) {
      const callback = this.changedCallback;
      if (callback !== null) {
        callback(next);
      }
    }
  }
}
