import * as ui from "../bindings/ui";
import { HandlerAction } from "../core/Action";
import { Disposable, disposeAll } from "../core/Disposable";
import { keyboardFocusVisible } from "../core/FocusVisibility";
import {
  BorderStyle,
  CursorStyle,
  KeyEventType,
  Orientation,
  PointerEventType,
  SemanticRole,
  Unit,
} from "../core/ffi";
import { Theme, activeTheme } from "../core/Theme";
import { FlexBox } from "../nodes";

function clamp(value: f32, min: f32, max: f32): f32 {
  if (value < min) {
    return min;
  }
  if (value > max) {
    return max;
  }
  return value;
}

export class Slider extends FlexBox {
  private readonly trackNode: FlexBox;
  private readonly thumbNode: FlexBox;
  private readonly disposables: Array<Disposable> = new Array<Disposable>();
  private changedCallback: ((value: f32) => void) | null = null;
  private disposed: bool = false;
  private dragging: bool = false;
  private focusedState: bool = false;
  private hoveredState: bool = false;
  private minValue: f32 = 0.0;
  private maxValue: f32 = 100.0;
  private stepValue: f32 = 1.0;
  private currentValue: f32 = 0.0;
  private lengthValue: f32 = 180.0;
  private trackThicknessValue: f32 = 6.0;
  private thumbSizeValue: f32 = 18.0;
  private orientationValue: Orientation = Orientation.Horizontal;

  constructor(value: f32 = 0.0) {
    super();
    this.trackNode = new FlexBox();
    this.thumbNode = new FlexBox();
    this.semanticRole(SemanticRole.Slider);
    this.focusable(true);
    this.requireInteractive();
    this.reflectSemanticDisabledFromEnabled();
    this.cursor(CursorStyle.Pointer);
    this.child(this.trackNode.positionAbsolute());
    this.child(this.thumbNode.positionAbsolute());
    this.track(activeTheme.addAction(new HandlerAction<Slider, Theme>(this, (slider: Slider, _theme: Theme): void => {
      slider.handleThemeChanged();
    })));
    this.track(keyboardFocusVisible.addAction(new HandlerAction<Slider, bool>(this, (slider: Slider, _visible: bool): void => {
      slider.handleThemeChanged();
    })));
    this.setValue(value, false);
    this.semanticOrientation(this.orientationValue);
    this.handleThemeChanged();
  }

  get value(): f32 {
    return this.currentValue;
  }

  min(value: f32): this {
    this.minValue = value;
    if (this.maxValue < value) {
      this.maxValue = value;
    }
    this.setValue(this.currentValue, false);
    return this;
  }

  max(value: f32): this {
    this.maxValue = value;
    if (this.minValue > value) {
      this.minValue = value;
    }
    this.setValue(this.currentValue, false);
    return this;
  }

  step(value: f32): this {
    this.stepValue = value > 0.0 ? value : 1.0;
    this.setValue(this.currentValue, false);
    return this;
  }

  length(value: f32): this {
    this.lengthValue = value > this.thumbSizeValue ? value : this.thumbSizeValue + 1.0;
    this.syncGeometry();
    return this;
  }

  orientation(value: Orientation): this {
    this.orientationValue = value == Orientation.Vertical ? Orientation.Vertical : Orientation.Horizontal;
    this.semanticOrientation(this.orientationValue);
    this.syncGeometry();
    return this;
  }

  onChanged(callback: ((value: f32) => void) | null): this {
    this.changedCallback = callback;
    return this;
  }

  destroy(): void {
    this.dispose();
    super.destroy();
  }

  _handlePointerEvent(eventType: PointerEventType, x: f32, y: f32, modifiers: u32 = 0): void {
    super._handlePointerEvent(eventType, x, y, modifiers);
    if (!this.isEnabled) {
      return;
    }
    if (eventType == PointerEventType.Enter) {
      this.hoveredState = true;
      this.syncVisualState();
      return;
    }
    if (eventType == PointerEventType.Leave) {
      this.hoveredState = false;
      if (!this.dragging) {
        this.syncVisualState();
      }
      return;
    }
    if (eventType == PointerEventType.Down) {
      this.dragging = true;
      this.capturePointer();
      this.updateValueFromPointer(x, y, true);
      this.syncVisualState();
      return;
    }
    if (eventType == PointerEventType.Move && this.dragging) {
      this.updateValueFromPointer(x, y, true);
      return;
    }
    if (eventType == PointerEventType.Up && this.dragging) {
      this.updateValueFromPointer(x, y, true);
      this.dragging = false;
      this.releasePointer();
      this.syncVisualState();
    }
  }

  _handleKeyEvent(eventType: KeyEventType, key: string, modifiers: u32): void {
    super._handleKeyEvent(eventType, key, modifiers);
    if (!this.isEnabled || eventType != KeyEventType.Down || modifiers != 0) {
      return;
    }
    if (key == "Home") {
      this.setValue(this.minValue, true);
      return;
    }
    if (key == "End") {
      this.setValue(this.maxValue, true);
      return;
    }
    let delta: f32 = 0.0;
    if (this.orientationValue == Orientation.Vertical) {
      if (key == "ArrowUp") {
        delta = this.stepValue;
      } else if (key == "ArrowDown") {
        delta = -this.stepValue;
      }
    } else {
      if (key == "ArrowRight") {
        delta = this.stepValue;
      } else if (key == "ArrowLeft") {
        delta = -this.stepValue;
      }
    }
    if (delta != 0.0) {
      this.setValue(this.currentValue + delta, true);
    }
  }

  _handleFocusChanged(focused: bool): void {
    super._handleFocusChanged(focused);
    this.focusedState = focused;
    this.handleThemeChanged();
  }

  protected _onEffectiveEnabledChanged(_isEnabled: bool): void {
    if (!this.isEnabled && this.dragging) {
      this.dragging = false;
      this.releasePointer();
    }
    this.handleThemeChanged();
  }

  private normalizeValue(value: f32): f32 {
    const clamped = clamp(value, this.minValue, this.maxValue);
    if (this.stepValue <= 0.0) {
      return clamped;
    }
    const snapped = <f32>Math.round((clamped - this.minValue) / this.stepValue) * this.stepValue;
    return clamp(this.minValue + snapped, this.minValue, this.maxValue);
  }

  private setValue(value: f32, emit: bool): void {
    const normalized = this.normalizeValue(value);
    if (normalized == this.currentValue) {
      this.syncGeometry();
      return;
    }
    this.currentValue = normalized;
    this.semanticValueRange(this.currentValue, this.minValue, this.maxValue);
    this.syncGeometry();
    if (emit) {
      const callback = this.changedCallback;
      if (callback !== null) {
        callback(this.currentValue);
      }
    }
  }

  private updateValueFromPointer(x: f32, y: f32, emit: bool): void {
    let localX = x;
    let localY = y;
    if (this.builtHandle != 0) {
      const bounds = ui.tryGetBounds(this.builtHandle);
      if (bounds !== null) {
        localX = x - unchecked(bounds[0]);
        localY = y - unchecked(bounds[1]);
      }
    }
    const available = this.lengthValue - this.thumbSizeValue;
    if (available <= 0.0) {
      return;
    }
    const offset = this.orientationValue == Orientation.Vertical
      ? available - clamp(localY - (this.thumbSizeValue * 0.5), 0.0, available)
      : clamp(localX - (this.thumbSizeValue * 0.5), 0.0, available);
    const fraction = clamp(offset / available, 0.0, 1.0);
    this.setValue(this.minValue + ((this.maxValue - this.minValue) * fraction), emit);
  }

  private syncGeometry(): void {
    const available = this.lengthValue > this.thumbSizeValue ? this.lengthValue - this.thumbSizeValue : 0.0;
    const fraction = this.maxValue > this.minValue
      ? (this.currentValue - this.minValue) / (this.maxValue - this.minValue)
      : 0.0;
    const clampedFraction = clamp(fraction, 0.0, 1.0);
    if (this.orientationValue == Orientation.Vertical) {
      this.width(this.thumbSizeValue, Unit.Pixel);
      this.height(this.lengthValue, Unit.Pixel);
      this.trackNode
        .width(this.trackThicknessValue, Unit.Pixel)
        .height(available, Unit.Pixel)
        .position((this.thumbSizeValue - this.trackThicknessValue) * 0.5, this.thumbSizeValue * 0.5);
      this.thumbNode.position(0.0, available - (available * clampedFraction));
    } else {
      this.width(this.lengthValue, Unit.Pixel);
      this.height(this.thumbSizeValue, Unit.Pixel);
      this.trackNode
        .width(available, Unit.Pixel)
        .height(this.trackThicknessValue, Unit.Pixel)
        .position(this.thumbSizeValue * 0.5, (this.thumbSizeValue - this.trackThicknessValue) * 0.5);
      this.thumbNode.position(available * clampedFraction, 0.0);
    }
    this.thumbNode.width(this.thumbSizeValue, Unit.Pixel).height(this.thumbSizeValue, Unit.Pixel);
    this.semanticValueRange(this.currentValue, this.minValue, this.maxValue);
  }

  private syncVisualState(): void {
    const theme = activeTheme.value;
    const accent = this.dragging
      ? theme.colors.accentPressed
      : (this.hoveredState ? theme.colors.accentHovered : theme.colors.accent);
    this.cornerRadius(theme.spacing.sm);
    this.border(
      2.0,
      this.focusedState && this.isEnabled && keyboardFocusVisible.value ? theme.colors.focusRing : theme.colors.background,
      BorderStyle.Solid,
    );
    this.padding(2.0, 2.0, 2.0, 2.0);
    this.opacity(this.isEnabled ? 1.0 : 0.6);
    this.trackNode.cornerRadius(this.trackThicknessValue * 0.5);
    this.trackNode.bgColor(theme.colors.scrollbarTrack);
    this.thumbNode.cornerRadius(this.thumbSizeValue * 0.5);
    this.thumbNode.bgColor(accent);
    this.thumbNode.border(1.0, theme.colors.surface, BorderStyle.Solid);
  }

  private handleThemeChanged(): void {
    if (this.disposed) {
      return;
    }
    this.cursor(this.isEnabled ? CursorStyle.Pointer : CursorStyle.Default);
    this.syncVisualState();
    this.syncGeometry();
  }

  private track(disposable: Disposable): void {
    this.disposables.push(disposable);
  }

  private dispose(): void {
    if (this.disposed) {
      return;
    }
    this.disposed = true;
    disposeAll(this.disposables);
  }
}
