function computeSidebarListViewportHeight(): f32 {
  const rootInnerHeight = viewportHeightSignal.value - 40.0;
  const sidebarInnerHeight = rootInnerHeight - 32.0;
  const reservedHeight =
    SIDEBAR_TITLE_BLOCK_HEIGHT +
    SIDEBAR_DESCRIPTION_BLOCK_HEIGHT +
    SPACING_MEDIUM +
    SIDEBAR_LIST_BOTTOM_PADDING;
  const available = sidebarInnerHeight - reservedHeight;
  return available > MIN_SIDEBAR_LIST_VIEWPORT_HEIGHT
    ? available
    : MIN_SIDEBAR_LIST_VIEWPORT_HEIGHT;
}

function computeMainContentViewportHeight(): f32 {
  const available = viewportHeightSignal.value - 40.0;
  return available > 0.0 ? available : 0.0;
}

function formatSelectionCountText(length: i32): string {
  if (length <= 0) {
    return "Selection: ";
  }
  return "Selection: " + length.toString() + (length == 1 ? " char" : " chars");
}

function requireDemoListItemText(container: FlexBox, childIndex: i32): Text {
  const child = container.getChildAt(childIndex);
  if (child === null) {
    unreachable();
  }
  return changetype<Text>(child);
}

function ensureDemoListItemTemplate(container: FlexBox): void {
  if (container.childCount > 0) {
    return;
  }
  const theme = activeTheme.value;
  const primary = new Text("");
  primary.font(FONT_REGULAR, 17.0);
  primary.textColor(demoPrimaryText(theme));
  primary.selectable();
  primary.semanticRole(SemanticRole.Heading);

  const detail = new Text("");
  detail.font(FONT_REGULAR, 13.0);
  detail.textColor(demoSubtleText(theme));
  detail.selectable();

  container
    .flexDirection(FlexDirection.Column)
    .width(FULL_SIZE, Unit.Star)
    .padding(12.0, 12.0, 12.0, 12.0)
    .child(primary)
    .child(new FlexBox().width(FULL_SIZE, Unit.Star).height(6.0, Unit.Pixel))
    .child(detail);
}

function bindDemoListItem(container: FlexBox, index: i32): void {
  ensureDemoListItemTemplate(container);
  const theme = activeTheme.value;
  container.bgColor((index & 1) == 0 ? demoCardBackground(theme) : demoCardBackgroundAlt(theme));
  container.cornerRadius(SURFACE_RADIUS_SMALL);
  container.border(SURFACE_BORDER_WIDTH, demoSurfaceBorder(theme));
  const primary = requireDemoListItemText(container, 0);
  const detail = requireDemoListItemText(container, 2);
  primary.textColor(demoPrimaryText(theme));
  detail.textColor(demoSubtleText(theme));
  const primaryLabel = "Item " + index.toString();
  primary.text(primaryLabel);
  primary.semanticLabel(primaryLabel);
  detail.text("Fixed height row.");
  detail.semanticLabel("Fixed height row.");
}

