    const primaryText = demoPrimaryText(theme);
    const mutedText = demoMutedText(theme);
    const subtleText = demoSubtleText(theme);
    const borderColor = demoSurfaceBorder(theme);
    const surfaceShadow = demoSurfaceShadow(theme);
    const strongShadow = demoStrongSurfaceShadow(theme);
    this.root.bgColor(theme.colors.background);
    this.accentSwatch
      .bgColor(theme.colors.accent)
      .cornerRadius(SURFACE_RADIUS_MEDIUM)
      .border(SURFACE_BORDER_WIDTH, borderColor)
      .dropShadow(strongShadow, 0.0, SURFACE_SHADOW_OFFSET_Y, SURFACE_SHADOW_BLUR);
    this.sidebarShell
      .bgColor(demoPanelBackground(theme))
      .cornerRadius(SURFACE_RADIUS_LARGE)
      .border(SURFACE_BORDER_WIDTH, borderColor)
      .dropShadow(surfaceShadow, 0.0, SURFACE_SHADOW_OFFSET_Y, SURFACE_SHADOW_BLUR);
    this.previewPanel
      .bgColor(demoSectionBackground(theme))
      .cornerRadius(SURFACE_RADIUS_LARGE)
      .border(SURFACE_BORDER_WIDTH, borderColor)
      .dropShadow(surfaceShadow, 0.0, SURFACE_SHADOW_OFFSET_Y, SURFACE_SHADOW_BLUR);
    this.foundationsCard
      .bgColor(demoPanelBackground(theme))
      .cornerRadius(SURFACE_RADIUS_MEDIUM)
      .border(SURFACE_BORDER_WIDTH, borderColor);
    this.commonControlsCard
      .bgColor(demoPanelBackground(theme))
      .cornerRadius(SURFACE_RADIUS_MEDIUM)
      .border(SURFACE_BORDER_WIDTH, borderColor);
    this.foundationsScopeBox
      .cornerRadius(SURFACE_RADIUS_SMALL)
      .border(SURFACE_BORDER_WIDTH, borderColor);
    this.inspectorPanel
      .bgColor(demoPanelBackground(theme))
      .cornerRadius(SURFACE_RADIUS_MEDIUM)
      .border(SURFACE_BORDER_WIDTH, borderColor)
      .dropShadow(surfaceShadow, 0.0, SURFACE_SHADOW_OFFSET_Y, SURFACE_SHADOW_BLUR);
    this.mainHeaderPanel
      .bgColor(demoHeaderBackground(theme))
      .cornerRadius(SURFACE_RADIUS_LARGE)
      .border(SURFACE_BORDER_WIDTH, borderColor)
      .dropShadow(strongShadow, 0.0, SURFACE_SHADOW_OFFSET_Y, HEADER_SHADOW_BLUR);
    this.navDemoCard
      .bgColor(demoPanelBackground(theme))
      .cornerRadius(SURFACE_RADIUS_MEDIUM)
      .border(SURFACE_BORDER_WIDTH, borderColor);
    const mainContentColumn = this.mainContentColumn;
    if (mainContentColumn !== null) {
      mainContentColumn.bgColor(demoPanelBackground(theme));
    }
    this.inspectorDivider.bgColor(demoDividerColor(theme));
    this.keyTargetBox
      .cornerRadius(SURFACE_RADIUS_SMALL)
      .border(SURFACE_BORDER_WIDTH, borderColor);
    this.homeNavLink
      .bgColor(demoButtonSecondaryBackground(theme))
      .border(SURFACE_BORDER_WIDTH, borderColor);
    this.settingsNavLink
      .bgColor(demoButtonSecondaryBackground(theme))
      .border(SURFACE_BORDER_WIDTH, borderColor);
    this.diagnosticsNavLink
      .bgColor(demoButtonSecondaryBackground(theme))
      .border(SURFACE_BORDER_WIDTH, borderColor);
    this.counterButton
