    this.inspectorLinkText.textColor(mutedText);
    this.inspectorDescriptionText.textColor(subtleText);
    this.mainHeadingText.textColor(primaryText);
    this.mainDescriptionText.textColor(mutedText);
    this.homeNavLinkText.textColor(primaryText);
    this.settingsNavLinkText.textColor(primaryText);
    this.diagnosticsNavLinkText.textColor(primaryText);
    this.navDemoHeadingText.textColor(primaryText);
    this.navDemoDescriptionText.textColor(mutedText);
    this.navDemoSummaryText.textColor(subtleText);
    this.navDemoCounterText.textColor(primaryText);
    this.navDemoBadgeText.textColor(rgb(0xf8, 0xfb, 0xff));
