import * as ui from "../bindings/ui";
import { flushCommit, markNeedsCommit, resetCommitState } from "./FrameScheduler";
import { HandleValue } from "./ffi";
import { Node } from "./Node";

let mountedRoot: Node | null = null;

export class Application {
  static mount(root: Node): Node {
    const previous = mountedRoot;
    if (previous !== null) {
      previous.destroy();
      mountedRoot = null;
    }

    resetCommitState();
    ui.reset();
    ui.resizeWindow(ui.getViewportWidth(), ui.getViewportHeight());
    root.build();
    ui.setRoot(root.builtHandle);
    mountedRoot = root;
    markNeedsCommit();
    return root;
  }

  static unmount(): void {
    const previous = mountedRoot;
    if (previous === null) {
      return;
    }
    previous.destroy();
    mountedRoot = null;
    resetCommitState();
  }

  static flushRenders(): void {
    const root = mountedRoot;
    if (root === null) {
      resetCommitState();
      return;
    }
    if (root.builtHandle == <u64>HandleValue.Invalid) {
      resetCommitState();
      return;
    }
    flushCommit();
  }
}
